/**
 * @suppress
 */
public object FfiConverterTypeSonataAndroidEngine: FfiConverter<SonataAndroidEngine, Pointer> {

    override fun lower(value: SonataAndroidEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): SonataAndroidEngine {
        return SonataAndroidEngine(value)
    }

    override fun read(buf: ByteBuffer): SonataAndroidEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: SonataAndroidEngine) = 8UL

    override fun write(value: SonataAndroidEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



