sealed class SonataAndroidException: kotlin.Exception() {
    
    class Engine(
        
        val `reason`: kotlin.String
        ) : SonataAndroidException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SonataAndroidException> {
        override fun lift(error_buf: RustBuffer.ByValue): SonataAndroidException = FfiConverterTypeSonataAndroidError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSonataAndroidError : FfiConverterRustBuffer<SonataAndroidException> {
    override fun read(buf: ByteBuffer): SonataAndroidException {
        

        return when(buf.getInt()) {
            1 -> SonataAndroidException.Engine(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SonataAndroidException): ULong {
        return when(value) {
            is SonataAndroidException.Engine -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SonataAndroidException, buf: ByteBuffer) {
        when(value) {
            is SonataAndroidException.Engine -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





